package io.knowledgebrain.integration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.integration.api.enabled",havingValue="true")
@RequestMapping("/api/spaces/{spaceId}/github/repositories/{repositoryId}/work-items")
final class GitHubWorkController {
 private final GitHubWorkStore store;private final GitHubStore repositories;private final GitHubClient remote;private final GitHubWorkClient work;private final GitHubController authority;private final MeterRegistry metrics;
 GitHubWorkController(GitHubWorkStore store,GitHubStore repositories,GitHubClient remote,GitHubWorkClient work,GitHubController authority,MeterRegistry metrics){this.store=store;this.repositories=repositories;this.remote=remote;this.work=work;this.authority=authority;this.metrics=metrics;}
 static long expected(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(h.size()!=1||!h.getFirst().matches("\"ghw(?:0|[1-9][0-9]{0,15})\""))throw GitHubRules.bad();try{long v=Long.parseLong(h.getFirst().substring(4,h.getFirst().length()-1));if(v>=9007199254740991L)throw GitHubRules.bad();return v;}catch(NumberFormatException e){throw GitHubRules.bad();}}
 void count(String type){metrics.counter("brain.integration.github.work","operation",type).increment();}
 @GetMapping("/{kind}/sync-state") ResponseEntity<GitHubWorkStore.State> state(@PathVariable String spaceId,@PathVariable String repositoryId,@PathVariable String kind,HttpServletRequest r){GitHubController.query(r,Set.of());UUID space=GitHubRules.id(spaceId),repo=GitHubRules.id(repositoryId);GitHubWorkClient.kind(kind);authority.authorize(space,r,false,GitHubController.trace(r));var state=store.state(space,repo,kind);count("state");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"ghw"+state.version()+"\"").body(state);}
 @PostMapping("/{kind}/sync") ResponseEntity<GitHubWorkStore.Synced> sync(@PathVariable String spaceId,@PathVariable String repositoryId,@PathVariable String kind,HttpServletRequest r)throws IOException{GitHubController.query(r,Set.of());UUID space=GitHubRules.id(spaceId),repo=GitHubRules.id(repositoryId);GitHubWorkClient.kind(kind);String trace=GitHubController.trace(r);UUID actor=authority.authorize(space,r,true,trace);String key=GitHubRules.key(GitHubController.one(r,"Idempotency-Key"));long expected=expected(r);if(authority.body(r,32).size()!=0)throw GitHubRules.bad();var result=store.replay(space,repo,kind,actor,key,expected);if(result==null){var state=store.state(space,repo,kind);if(state.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Work sync changed; reload current state");if(!state.repositoryState().equals("ACTIVE"))throw GitHubWorkStore.conflict();var parent=repositories.get(space,repo);var source=remote.repository(GitHubRules.url(parent.url()));if(!source.externalId().equals(parent.externalId())||!source.fullName().equals(parent.fullName()))throw GitHubWorkStore.conflict();var batch=work.fetch(source,kind);if(!actor.equals(authority.authorize(space,r,true,trace)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Principal changed");result=store.sync(space,repo,kind,actor,key,expected,batch,trace.substring(3,35));}count(result.replay()?"replay":"sync");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"ghw"+result.state().version()+"\"").body(result);}
 @GetMapping ResponseEntity<GitHubWorkStore.Page<GitHubWorkStore.Item>> page(@PathVariable String spaceId,@PathVariable String repositoryId,HttpServletRequest r){GitHubController.query(r,Set.of("kind","state","after","limit"));UUID space=GitHubRules.id(spaceId),repo=GitHubRules.id(repositoryId);authority.authorize(space,r,false,GitHubController.trace(r));String kind=Optional.ofNullable(r.getParameter("kind")).orElse("PULL_REQUEST"),state=Optional.ofNullable(r.getParameter("state")).orElse("ALL");UUID after=r.getParameter("after")==null?null:GitHubRules.id(r.getParameter("after"));var page=store.page(space,repo,kind,state,after,(int)GitHubController.number(r.getParameter("limit"),20,100));count("catalog");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(page);}
 @GetMapping("/{itemId}") ResponseEntity<GitHubWorkStore.Item> get(@PathVariable String spaceId,@PathVariable String repositoryId,@PathVariable String itemId,HttpServletRequest r){GitHubController.query(r,Set.of());UUID space=GitHubRules.id(spaceId),repo=GitHubRules.id(repositoryId),item=GitHubRules.id(itemId);authority.authorize(space,r,false,GitHubController.trace(r));var value=store.get(space,repo,item);count("read");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag("\"ghwi"+value.version()+"\"").body(value);}
 @GetMapping("/{itemId}/revisions") ResponseEntity<List<GitHubWorkStore.Revision>> history(@PathVariable String spaceId,@PathVariable String repositoryId,@PathVariable String itemId,HttpServletRequest r){GitHubController.query(r,Set.of("before","limit"));UUID space=GitHubRules.id(spaceId),repo=GitHubRules.id(repositoryId),item=GitHubRules.id(itemId);authority.authorize(space,r,false,GitHubController.trace(r));var rows=store.history(space,repo,item,GitHubController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)GitHubController.number(r.getParameter("limit"),5,10));count("history");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(rows);}
 @GetMapping("/{kind}/syncs") ResponseEntity<GitHubWorkStore.SyncPage> syncs(@PathVariable String spaceId,@PathVariable String repositoryId,@PathVariable String kind,HttpServletRequest r){GitHubController.query(r,Set.of("before","limit"));UUID space=GitHubRules.id(spaceId),repo=GitHubRules.id(repositoryId);GitHubWorkClient.kind(kind);authority.authorize(space,r,false,GitHubController.trace(r));Long before=r.getParameter("before")==null?null:GitHubController.number(r.getParameter("before"),0,Long.MAX_VALUE);count("sync-history");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.syncs(space,repo,kind,before,(int)GitHubController.number(r.getParameter("limit"),20,100)));}
}
